/**
 * @name Network injection via socket operations
 * @description Using untrusted input in socket connections could lead to SSRF or other network attacks
 * @kind path-problem
 * @problem.severity high
 * @id py/network-injection
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module NetworkInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Socket connections
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember(["connect", "bind", "sendto"]).getACall() and
      sink = call.getArg(0)
    ) or
    // DNS lookups
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember(["gethostbyname", "getaddrinfo"]).getACall() and
      sink = call.getArg(0)
    ) or
    // asyncio network operations  
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("asyncio").getMember("open_connection").getACall() and
      sink = call.getArg(0)
    )
  }
}

module NetworkInjectionFlow = TaintTracking::Global<NetworkInjectionConfig>;
import NetworkInjectionFlow::PathGraph

from NetworkInjectionFlow::PathNode source, NetworkInjectionFlow::PathNode sink
where NetworkInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Network injection from $@.", source.getNode(), "user input"

/**
 * @name Unsafe socket operations with untrusted input
 * @description Socket operations using untrusted input could lead to network-based attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/unsafe-socket-operation
 * @tags security
 *        external/cwe/cwe-020
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SocketOperationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Socket operations that take host/port parameters
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember(["connect", "connect_ex"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember("create_connection").getACall() and
      sink = call.getArg(0)
    )
  }
}

module SocketOperationFlow = TaintTracking::Global<SocketOperationConfig>;
import SocketOperationFlow::PathGraph

from SocketOperationFlow::PathNode source, SocketOperationFlow::PathNode sink
where SocketOperationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Socket operation using untrusted input from $@.", source.getNode(), "user input"

